        auto &f = test.fixture; auto &c = f.controller;
        c.saveOwnStatus("Retired", "☕", true);
        QTRY_COMPARE(test.posts, 1); QTRY_VERIFY(bool(test.release)); QTRY_VERIFY(test.pending());
