        test.direct.fixture.users = [&](const Request &) {
            Response response{test.directory};
            if(hold) { hold=false; response.defer=[&](std::function<void()> send){release=std::move(send);}; }
            return response;
        };
        auto releaseOnExit=qScopeGuard([&] { if(release) release(); });
