        QTRY_VERIFY_WITH_TIMEOUT(([&] {
            row = modelMessage(fixture.controller, returnedId);
            return row.value("quoteStatus").toString() == QLatin1String("ready");
        })(), 9000);
        QCOMPARE(row.value("quoteContent").toString(), QString("far origin"));
