        blank["author_uuid"] = "9a9a9a9a-9a9a-4a9a-8a9a-9a9a9a9a9a9a";
        auto second = message(QStringLiteral("Alpha second note"),
                              QStringLiteral("12121212-1212-4212-8212-121212121212"));
