    // Fix round R1 (cid=4577117364, cid=4577117373): the copy paths must bound
    // the bytes they read. A staged file over the 64 MiB clipboard cap is
    // rejected quietly, but reading it with readAll() first materialises the
    // whole payload - the test grows the staged slot file into a 200 MiB sparse
    // file (near-zero disk cost) and asserts peak RSS stays bounded, which an
    // unbounded readAll() cannot pass.
    void mediaViewerCopyRejectsOversizedStagedFileWithoutLoadingItWhole()
    {
        Fixture fixture;
        FileClient files(&fixture.api);
        fixture.controller.useFiles(&files);
        const QByteArray png = clipboardCopyFixturePng();
        const auto sha = QString::fromLatin1(QCryptographicHash::hash(png, QCryptographicHash::Sha256).toHex());
        fixture.files = [&](const Request &request) {
            if (request.target.path().endsWith("/actions/download")) {
                Response result;
                result.rawBody = png;
                result.rawContentType = "image/png";
                return result;
            }
            return Response{QJsonObject{{"uuid", mvFileA}, {"stream_uuid", streamId}, {"name", "m1.png"},
                {"content_type", "image/png"}, {"size_bytes", png.size()}, {"hash", sha}}};
        };
        QVERIFY(fixture.start());
        auto *viewer = fixture.controller.mediaViewer();
        QVariantList rows;
        rows << mediaViewerRow("m1", mvFileA);
        QVERIFY(viewer->openFromMessages(rows, mvFileA));
        QTRY_COMPARE_WITH_TIMEOUT(viewer->items().at(0).toMap().value("state").toString(), QStringLiteral("ready"), 4000);
        const auto staged = QUrl(viewer->items().at(0).toMap().value("url").toString()).toLocalFile();
        {
            QFile file(staged);
            QVERIFY(file.open(QIODevice::ReadWrite));
            QVERIFY(file.resize(200 * 1024 * 1024));
        }
        setClipboardImageSentinel();
        resetPeakResidentMemory();
        const auto baseline = peakResidentBytes();
        // Over the cap: rejected silently, clipboard untouched, and the read is
        // bounded - the whole 200 MiB must never be loaded.
        QVERIFY(!viewer->copyCurrentImage());
        const auto growth = peakResidentBytes() - baseline;
        // The bound itself: a correct copy reads at most 64 MiB + 1 byte, so a
        // generous 96 MiB growth ceiling separates it from a 200 MiB readAll().
        QVERIFY2(growth < 96LL * 1024 * 1024,
            qPrintable(QStringLiteral("peak RSS grew by %1 MiB").arg(growth / (1024 * 1024))));
        QVERIFY(clipboardSentinelIntact());
        QVERIFY(fixture.controller.error().isEmpty());
        viewer->close();
    }

    // Fix round R1 (cid=4577117378): the download completion is bound to the
    // session that started it. A completion that lands after the identity is
    // switched must be discarded; it may not put the old session's image on the
    // system clipboard. The switch goes through Session::selectProject (the
    // same-token account-switch boundary), so the in-flight download still
    // completes after the identity moved on.
    void copyMessageImageCompletionAfterSessionEndIsDiscarded()
    {
        const QString otherProject = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
        bool secondProject = false;
        Fixture fixture;
        fixture.authentication = [&](const Request &request) {
            auto response = sessionResponse(request);
            if (request.target.path() == "/api/core/v1/iam/projects/")
                response.data = QJsonArray{QJsonObject{{"uuid", projectId}, {"name", "First project"}, {"status", "ACTIVE"}},
                    QJsonObject{{"uuid", otherProject}, {"name", "Second project"}, {"status", "ACTIVE"}}};
            if (secondProject && request.target.path().endsWith("/actions/introspect")) {
                auto raw = response.data.toObject();
                raw["project_id"] = otherProject;
                response.data = raw;
            }
            return response;
        };
        fixture.streams = [&](const Request &) {
            if (secondProject) return Response{QJsonArray{}};
            return Response{QJsonArray{QJsonObject{{"uuid", streamId}, {"project_id", projectId},
                {"name", "Native channel"}, {"encryption", false}}}};
        };
        fixture.topics = [&](const Request &) {
            if (secondProject) return Response{QJsonArray{}};
            return Response{QJsonArray{QJsonObject{{"uuid", topicId}, {"project_id", projectId},
                {"stream_uuid", streamId}, {"name", "Native topic"}}}};
        };
        FileClient files(&fixture.api);
        fixture.controller.useFiles(&files);
        const QByteArray png = clipboardCopyFixturePng();
        const auto sha = QString::fromLatin1(QCryptographicHash::hash(png, QCryptographicHash::Sha256).toHex());
        int downloadRequests = 0;
        fixture.files = [&](const Request &request) {
            if (request.target.path().endsWith("/actions/download")) {
                ++downloadRequests;
                Response result;
                result.rawBody = png;
                result.rawContentType = "image/png";
                result.delay = 500; // the completion lands after the identity switch
                return result;
            }
            return Response{QJsonObject{{"uuid", mvFileA}, {"stream_uuid", streamId}, {"name", "m1.png"},
                {"content_type", "image/png"}, {"size_bytes", png.size()}, {"hash", sha}}};
        };
        const auto body = QStringLiteral("Head\n\n![m1.png](urn:image:%1?name=m1.png&content_type=image%2Fpng&size=%2)\n\nTail")
            .arg(mvFileA).arg(png.size());
        const auto note = message(body, messageId);
        fixture.messages = [&](const Request &request) -> Response {
            if (request.method == "GET") return {QJsonArray{note}};
            return {message("answer", returnedId), 201};
        };
        fixture.controller.login(fixture.server.origin().toString(), "synthetic-user", "synthetic-password", "");
        QTRY_COMPARE_WITH_TIMEOUT(fixture.controller.projects().size(), 2, 2000);
        fixture.controller.openProject(projectId);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.authenticated(), 2000);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.streams().size() == 1, 2000);
        fixture.controller.selectStream(streamId);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.controller.topics().isEmpty(), 2000);
        fixture.controller.selectTopic(topicId);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.controller.busy(), 2000);
        setClipboardImageSentinel();
        QVERIFY(fixture.controller.copyMessageImage(messageId));
        QTRY_VERIFY_WITH_TIMEOUT(downloadRequests >= 1, 4000);
        secondProject = true;
        fixture.session.selectProject(otherProject);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.authenticated(), 2000);
        // Let the delayed completion fire; it belongs to the retired identity.
        QTest::qWait(1500);
        // A stale completion must not put the previous session's image on the system clipboard.
        QVERIFY(clipboardSentinelIntact());
    }

    // Fix round R2 (cid=4577609973, cid=4577609975): the owner key alone is not
    // a completion fence. A project switch away and back re-creates the very
    // same creationOwnerKey, so a download dispatched before the detour would
    // pass the R1 fence after its session already retired and write its image
    // into the current clipboard. The controller now also fences on a session
    // generation that advances on every retirement boundary, and this test
    // stages the in-flight download with the mock's defer gate (no sleeps):
    // the response is delivered only after the session has returned to the
    // first project, and the reply's finish proves the delivery landed - so a
    // still-intact sentinel means the completion was discarded, not lost.
    void copyMessageImageCompletionAfterProjectRoundTripIsDiscarded()
    {
        const QString otherProject = "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
        bool secondProject = false;
        std::function<void()> releaseDownload;
        Fixture fixture;
        fixture.authentication = [&](const Request &request) {
            auto response = sessionResponse(request);
            if (request.target.path() == "/api/core/v1/iam/projects/")
                response.data = QJsonArray{QJsonObject{{"uuid", projectId}, {"name", "First project"}, {"status", "ACTIVE"}},
                    QJsonObject{{"uuid", otherProject}, {"name", "Second project"}, {"status", "ACTIVE"}}};
            if (secondProject && request.target.path().endsWith("/actions/introspect")) {
                auto raw = response.data.toObject();
                raw["project_id"] = otherProject;
                response.data = raw;
            }
            return response;
        };
        fixture.streams = [&](const Request &) {
            if (secondProject) return Response{QJsonArray{}};
            return Response{QJsonArray{QJsonObject{{"uuid", streamId}, {"project_id", projectId},
                {"name", "Native channel"}, {"encryption", false}}}};
        };
        fixture.topics = [&](const Request &) {
            if (secondProject) return Response{QJsonArray{}};
            return Response{QJsonArray{QJsonObject{{"uuid", topicId}, {"project_id", projectId},
                {"stream_uuid", streamId}, {"name", "Native topic"}}}};
        };
        FileClient files(&fixture.api);
        fixture.controller.useFiles(&files);
        const QByteArray png = clipboardCopyFixturePng();
        const auto sha = QString::fromLatin1(QCryptographicHash::hash(png, QCryptographicHash::Sha256).toHex());
        int downloadRequests = 0;
        fixture.files = [&](const Request &request) {
            if (request.target.path().endsWith("/actions/download")) {
                ++downloadRequests;
                Response result;
                result.rawBody = png;
                result.rawContentType = "image/png";
                // Hold only the in-flight copy dispatched below; the post-return
                // proof copy answers immediately.
                if (downloadRequests == 1)
                    result.defer = [&releaseDownload](std::function<void()> send) { releaseDownload = std::move(send); };
                return result;
            }
            return Response{QJsonObject{{"uuid", mvFileA}, {"stream_uuid", streamId},
                {"name", "m1.png"}, {"content_type", "image/png"}, {"size_bytes", png.size()}, {"hash", sha}}};
        };
        const auto body = QStringLiteral("Head\n\n![m1.png](urn:image:%1?name=m1.png&content_type=image%2Fpng&size=%2)\n\nTail")
            .arg(mvFileA).arg(png.size());
        const auto note = message(body, messageId);
        fixture.messages = [&](const Request &request) -> Response {
            if (request.method == "GET") return {QJsonArray{note}};
            return {message("answer", returnedId), 201};
        };
        // Never leave the mock socket with an undelivered deferred gate if an
        // assertion below aborts the test.
        auto releaseOnExit = qScopeGuard([&] { if (releaseDownload) releaseDownload(); });
        fixture.controller.login(fixture.server.origin().toString(), "synthetic-user", "synthetic-password", "");
        QTRY_COMPARE_WITH_TIMEOUT(fixture.controller.projects().size(), 2, 2000);
        fixture.controller.openProject(projectId);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.authenticated(), 2000);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.streams().size() == 1, 2000);
        fixture.controller.selectStream(streamId);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.controller.topics().isEmpty(), 2000);
        fixture.controller.selectTopic(topicId);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.controller.busy(), 2000);
        setClipboardImageSentinel();
        QVERIFY(fixture.controller.copyMessageImage(messageId));
        QTRY_VERIFY_WITH_TIMEOUT(downloadRequests >= 1, 4000);
        QTRY_VERIFY_WITH_TIMEOUT(bool(releaseDownload), 2000);
        // Track the in-flight download reply so the deferred delivery can be
        // proven (not assumed) once released.
        QPointer<QNetworkReply> inFlight;
        for (auto *reply : fixture.api.findChildren<QNetworkReply *>())
            if (!reply->isFinished() && reply->url().path().endsWith("/actions/download")) inFlight = reply;
        QVERIFY(inFlight);
        QVERIFY(!inFlight->isFinished());
        // Detour to the second project and back: the owner key the completion
        // sees at the end is identical to the one captured at dispatch.
        secondProject = true;
        fixture.session.selectProject(otherProject);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.authenticated(), 2000);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.controller.busy(), 2000);
        secondProject = false;
        fixture.session.selectProject(projectId);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.authenticated(), 2000);
        QTRY_VERIFY_WITH_TIMEOUT(fixture.controller.streams().size() == 1, 2000);
        // Deliver the retired operation's response now.
        releaseDownload();
        releaseDownload = nullptr;
        QTRY_VERIFY_WITH_TIMEOUT(inFlight.isNull() || inFlight->isFinished(), 4000);
        // The response landed but the completion belongs to a retired session
        // generation: the clipboard keeps the sentinel even though the owner
        // key matches again.
        QVERIFY(clipboardSentinelIntact());
        // Non-vacuity: a fresh copy under the current generation still writes
        // the image through the very same pipeline. First let the returned
        // session re-open the conversation the message lives in.
        fixture.controller.selectStream(streamId);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.controller.topics().isEmpty(), 2000);
        fixture.controller.selectTopic(topicId);
        QTRY_VERIFY_WITH_TIMEOUT(!fixture.controller.messages().isEmpty(), 4000);
        QGuiApplication::clipboard()->clear();
        QVERIFY(fixture.controller.copyMessageImage(messageId));
        QTRY_VERIFY_WITH_TIMEOUT(!QGuiApplication::clipboard()->image().isNull(), 4000);
        QCOMPARE(QGuiApplication::clipboard()->image().size(), QSize(8, 4));
    }

    // The controller-side half of docs/NATIVE_DESKTOP_AUTO_PAGING.md: a fetched
    // page whose every row is an account-irrelevant service entry must still
    // commit and move the older marker. The view-side zero-visible auto-advance
    // walks through exactly such pages, so marker traversal has to survive them.
    void allFilteredServicePageStillAdvancesMarkers()
    {
        Fixture fixture;
        const auto announcedRow = [&](int number) {
            auto entry = message(QString("Announced %1").arg(number),
                QString("88000000-0000-4000-8000-%1").arg(number, 12, 10, QLatin1Char('0')));
            entry["payload"] = QJsonObject{{"kind", "key_announced"},
                {"key_uuid", QString("77000000-0000-4000-8000-%1").arg(number, 12, 10, QLatin1Char('0'))}};
            return entry;
        };
        fixture.messages = [&](const Request &request) -> Response {
            const auto marker = QUrlQuery(request.target).queryItemValue("page_marker");
            if (marker.isEmpty()) {
                Response response{QJsonArray{announcedRow(12), announcedRow(11)}};
                response.headers.insert("X-Pagination-Marker", "svc-2");
                return response;
            }
            if (marker == "svc-2")
                return Response{QJsonArray{announcedRow(10), announcedRow(9)}};
            return Response{QJsonObject{}, 404};
        };
        QVERIFY(fixture.start());
        QTRY_COMPARE(fixture.controller.messages().size(), 2);
        QVERIFY(fixture.controller.canLoadOlder()); // a fully filtered page keeps the traversal alive
        fixture.controller.loadOlder();
        QTRY_COMPARE(fixture.controller.messages().size(), 4);
        QVERIFY(!fixture.controller.canLoadOlder()); // the final page carried no marker
    }

    void overlayBannerTransportDropFlipsPhaseOfflineThenRecovers()
    {
        Fixture fixture;
        QVERIFY(fixture.start());
        QCOMPARE(fixture.controller.connectionPhase(), QString("online"));
        QCOMPARE(fixture.controller.connectionSeverity(), QString("warning"));
        QVERIFY(!fixture.controller.bootstrapError());
        const auto base = fixture.server.handler;
        // The outage window drops every request the snapshot issues, so an
        // unrelated in-flight success cannot clear the offline phase early.
        fixture.server.handler = [base](const Request &request) {
            const auto path = request.target.path();
            if (request.method == "GET"
                && (path.endsWith("/streams/") || path.endsWith("/users/"))) {
                Response dropped; dropped.abortConnection = true; return dropped;
            }
            return base(request);
        };
        fixture.controller.refresh();
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("offline"));
        QCOMPARE(fixture.controller.connectionSeverity(), QString("critical"));
        // Restoring the server and letting a response land clears the banner.
        fixture.server.handler = base;
        fixture.controller.refresh();
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("online"));
        QTRY_COMPARE(fixture.controller.streams().size(), 1);
    }

    void overlayBannerRateLimitShowsCountdownUntilItExpires()
    {
        Fixture fixture;
        QVERIFY(fixture.start());
        const auto base = fixture.server.handler;
        auto limitedFor = [base](const QString &seconds) {
            return [base, seconds](const Request &request) {
                if (request.method == "GET" && request.target.path().endsWith("/streams/")) {
                    Response limited{QJsonArray{}, 429};
                    limited.headers.insert("Retry-After", seconds.toLatin1());
                    return limited;
                }
                return base(request);
            };
        };
        fixture.server.handler = limitedFor("1");
        fixture.controller.refresh();
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("rate_limited"));
        QCOMPARE(fixture.controller.connectionSeverity(), QString("warning"));
        QVERIFY(fixture.controller.connectionRetryInSeconds() >= 1);
        // The countdown runs out even while the server answers again.
        fixture.server.handler = base;
        QTRY_COMPARE_WITH_TIMEOUT(fixture.controller.connectionPhase(), QString("online"), 5000);
        // A generous Retry-After stays announced with its remaining seconds.
        fixture.server.handler = limitedFor("42");
        fixture.controller.refresh();
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("rate_limited"));
        const auto remaining = fixture.controller.connectionRetryInSeconds();
        QVERIFY2(remaining > 30 && remaining <= 42, qPrintable(QString::number(remaining)));
    }

    void overlayBannerBootstrapFailureClearsAfterRetrySucceeds()
    {
        Fixture fixture;
        QVERIFY(fixture.start());
        QVERIFY(!fixture.controller.bootstrapError());
        const auto base = fixture.server.handler;
        // A malformed catalog row is a bootstrap failure: the snapshot is
        // cancelled and reported (report -> cancelSnapshot -> snapshotFailed).
        fixture.server.handler = [base](const Request &request) {
            if (request.method == "GET" && request.target.path().endsWith("/streams/"))
                return Response{QJsonArray{QJsonObject{{"uuid", QStringLiteral("not-a-uuid")}}}};
            return base(request);
        };
        fixture.controller.refresh();
        QTRY_VERIFY(fixture.controller.bootstrapError());
        QVERIFY(!fixture.controller.error().isEmpty());
        fixture.server.handler = base;
        fixture.controller.retryBootstrap();
        QTRY_VERIFY(!fixture.controller.bootstrapError());
        QVERIFY(fixture.controller.error().isEmpty());
        QTRY_COMPARE(fixture.controller.streams().size(), 1);
    }

    void overlayBannerRealtimeDropShowsReconnectingAndReconnectClears()
    {
        Fixture fixture; RealtimeGateway gateway(fixture.server.serverPort());
        fixture.realtime = [](const Request &request) {
            if (request.target.path().endsWith("/epoch/"))
                return Response{QJsonObject{{"epoch_generation", "controller-generation"},
                    {"epoch_version", 10}, {"current_epoch_version", 10}, {"minimum_epoch_version", 1}}};
            return Response{QJsonArray{}};
        };
        QVERIFY(fixture.start(gateway.origin()));
        RealtimeClient realtime(&fixture.api, &fixture.session);
        fixture.controller.useRealtime(&realtime);
        QTRY_COMPARE(fixture.controller.syncState(), QString("live"));
        QCOMPARE(fixture.controller.connectionPhase(), QString("online"));
        gateway.sockets.first()->close();
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("reconnecting"));
        // The gateway accepts the reconnect again and the banner clears itself.
        QTRY_COMPARE_WITH_TIMEOUT(fixture.controller.connectionPhase(), QString("online"), 15000);
    }

    // exo-review finding 1: a server that never answers must mark the
    // connection offline when the client request timeout fires.
    void overlayBannerRequestTimeoutMarksConnectionOffline()
    {
        // Handler captures must outlive the Fixture and every deferred send.
        QVector<std::function<void()>> held;
        Fixture fixture;
        QVERIFY(fixture.start());
        QCOMPARE(fixture.controller.connectionPhase(), QString("online"));
        // An outage window that never answers: the requests are neither
        // completed nor refused, so the client timeout fires without any
        // HTTP response - a transport-level failure for connection health.
        fixture.server.handler = [&held](const Request &) {
            Response hold{QJsonArray{}};
            hold.defer = [&held](std::function<void()> send) { held.append(std::move(send)); };
            return hold;
        };
        fixture.controller.refresh();
        // ApiClient::RequestTimeoutMs is 30 s; wait out the client timer.
        QTRY_COMPARE_WITH_TIMEOUT(fixture.controller.connectionPhase(), QString("offline"), 35000);
        QCOMPARE(fixture.controller.connectionSeverity(), QString("critical"));
        held.clear(); // never released: teardown aborts the pending requests
    }

    // exo-review finding 2: a later 429 with a shorter Retry-After must not
    // shorten an already announced rate-limit countdown.
    void overlayBannerRateLimitKeepsTheLaterRetryDeadline()
    {
        Fixture fixture;
        QVERIFY(fixture.start());
        const auto base = fixture.server.handler;
        auto limitedFor = [base](const QString &seconds) {
            return [base, seconds](const Request &request) {
                if (request.method == "GET" && request.target.path().endsWith("/streams/")) {
                    Response limited{QJsonArray{}, 429};
                    limited.headers.insert("Retry-After", seconds.toLatin1());
                    return limited;
                }
                return base(request);
            };
        };
        fixture.server.handler = limitedFor("60");
        fixture.controller.refresh();
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("rate_limited"));
        const auto announced = fixture.controller.connectionRetryInSeconds();
        QVERIFY2(announced > 50, qPrintable(QString::number(announced)));
        // A racing response with a shorter Retry-After arrives afterwards.
        QSignalSpy snapshotFailed(&fixture.controller, &NativeController::snapshotFailed);
        QVERIFY(snapshotFailed.isValid());
        fixture.server.handler = limitedFor("5");
        fixture.controller.refresh();
        // The callback that fails the snapshot runs after the transport
        // observer has already seen this second 429.
        QVERIFY(snapshotFailed.wait(5000));
        const auto remaining = fixture.controller.connectionRetryInSeconds();
        QVERIFY2(remaining > 30 && remaining <= announced, qPrintable(QString::number(remaining)));
    }

    // exo-review finding 3: a successful realtime reconnect must clear a
    // stale transport-offline flag even when no JSON response was observed.
    void overlayBannerRealtimeReconnectClearsTransportOffline()
    {
        // Handler captures must outlive the Fixture and every deferred send.
        QVector<std::function<void()>> heldCatchUps;
        auto holdNextCatchUp = std::make_shared<bool>(false);
        Fixture fixture; fixture.extraTopic = true;
        RealtimeGateway gateway(fixture.server.serverPort());
        fixture.realtime = [holdNextCatchUp, &heldCatchUps](const Request &request) {
            if (request.target.path().endsWith("/epoch/"))
                return Response{QJsonObject{{"epoch_generation", "controller-generation"},
                    {"epoch_version", 10}, {"current_epoch_version", 10}, {"minimum_epoch_version", 1}}};
            Response response{QJsonArray{}};
            if (*holdNextCatchUp) {
                *holdNextCatchUp = false;
                response.defer = [&heldCatchUps](std::function<void()> send) { heldCatchUps.append(std::move(send)); };
            }
            return response;
        };
        QVERIFY(fixture.start(gateway.origin()));
        RealtimeClient realtime(&fixture.api, &fixture.session);
        fixture.controller.useRealtime(&realtime);
        QTRY_COMPARE(fixture.controller.syncState(), QString("live"));
        QCOMPARE(fixture.controller.connectionPhase(), QString("online"));
        // Stall the reconnect catch-up so the websocket cannot report live
        // before the transport outage below has been observed by the client.
        *holdNextCatchUp = true;
        gateway.sockets.first()->close();
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("reconnecting"));
        QTRY_VERIFY(!heldCatchUps.isEmpty());
        // A controller request that dies at the transport level marks the
        // connection offline while realtime is still down.
        fixture.messages = [](const Request &) {
            Response dropped; dropped.abortConnection = true; return dropped;
        };
        fixture.controller.selectTopic(secondTopicId);
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("offline"));
        // The websocket reconnect completes without observing any JSON
        // response; a healthy realtime link must not leave the offline
        // banner set on top of live sync state.
        const auto catchUps = heldCatchUps;
        heldCatchUps.clear();
        for (const auto &send : catchUps)
            send();
        QTRY_COMPARE_WITH_TIMEOUT(fixture.controller.syncState(), QString("live"), 15000);
        QTRY_COMPARE(fixture.controller.connectionPhase(), QString("online"));
    }

