        const QString unknownStream = "ffffffff-ffff-4fff-8fff-ffffffffffff";
        const QString sourceA = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
        const QString targetTopic = "dddddddd-dddd-4ddd-8ddd-dddddddddddd";
